  async listBoundProjectIds(rubricId: string): Promise<string[]> {
    const res = await this.pool.query<{ project_id: string }>(
      'SELECT project_id FROM project_rubric_bindings WHERE rubric_id = $1 ORDER BY project_id',
      [rubricId],
    );
