    ] },
  ],
  created_at: '2026-11-16T00:00:00.000Z',
  updated_at: '2026-11-16T00:00:00.000Z',
};

const review = (role: Review['reviewer_role'], score: number, t: string): Review => ({
  id: t,
  project_id: 'p',
  rubric_id: 'r1',
  reviewer_id: `u-${t}`,
  reviewer_role: role,
  scores: [],
  comments: null,
  overall_score: score,
  created_at: t,
  updated_at: t,
});

describe('scoring', () => {
